    m, n = len(s1), len(s2)
    # Initialize distance matrix
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: distance to empty string
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

