    if n == 1:
        return s

    # dp[i][j] indicates whether s[i:j+1] is a palindrome
    dp = [[False] * n for _ in range(n)]
    longest_start = 0
    longest_len = 1

    # All single characters are palindromes
    for i in range(n):
        dp[i][i] = True

    # Check substrings of length 2
