def rotated_binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = arr[mid]

        # Check if target is at mid
        if mid_val == target:
            return mid

        # Determine which side the pivot is on
        if mid_val > arr[left]:
            # Left side is rotated, so target could be in left or right
            if target >= mid_val and target <= arr[left]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right side is rotated, so target could be in left or right
            if target >= arr[mid] and target <= mid_val:
                right = mid - 1
            else:
                left = mid + 1

    return -1
