    # DP table: dp[i][j] = min operations to transform str1[:i] -> str2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i  # insert all characters of str2
    for j in range(n + 1):
        dp[0][j] = j  # delete all characters of str1

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
