def rotated_binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = arr[mid]

        # Check if mid is the target
        if mid_val == target:
            return mid

        # Determine which side the pivot is on
        if mid_val > arr[right]:
            # Pivot is in the right half
            left = mid + 1
        else:
            # Pivot is in the left half
