        actual (list): List of integers or strings ('0' or '1') representing actual labels.
        predicted (list): List of integers or strings ('0' or '1') representing predicted labels.

    Returns:
        int: Number of misclassifications.
    """
    def to_int(x):
        if isinstance(x, int):
            return x
        if isinstance(x, str):
            return int(x)
        raise ValueError(f"Unsupported type: {type(x)}")

    n = len(actual)
    misclassifications = 0

    for i in range(n):
        actual_label = to_int(actual[i])
        predicted_label = to_int(predicted[i])

        if actual_label != predicted_label:
            misclassifications += 1

    return misclassifications

