def min_subarray_len_with_prime(s, nums):
    n = len(nums)
    if n == 0:
        return 0

    # Precompute prime status for numbers up to max_abs + s (to cover sums)
    max_val = max(abs(num) for num in nums) + s
    is_prime = [True] * (max_val + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_val ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, max_val + 1, i):
                is_prime[j] = False

    min_len = float('inf')
    current_sum = 0
    start = 0

    for end in range(n):
        current_sum += nums[end]
        # If current_sum >= s and we have a prime in the subarray [start, end]
        if current_sum >= s and is_prime[current_sum]:
            # Check if subarray [start, end] contains at least one prime
            has_prime = any(is_prime[x] for x in nums[start:end+1])
            if has_prime:
                min_len = min(min_len, end - start + 1)
        # Slide window
        if current_sum > s:
            current_sum -= nums[start]
