def primeList(head):
    # If the list is empty or has only one node, return as is
    if not head or not head.next:
        return head

    # We'll traverse the list and replace each node's value with the smallest prime > val
    # If that prime > 2 * val, we subtract val from it before updating.

    current = head
    # We need to find the next prime manually
    def find_next_prime(n):
        if n <= 1:
            return 2
        if n == 2:
            return 2
        if n % 2 == 0:
            return 3
        i = 3
        while True:
            candidate = n + i
            is_prime = True
            # Check divisibility up to sqrt(candidate)
            limit = int(candidate ** 0.5) + 1
            for d in range(3, limit, 2):
                if candidate % d == 0:
                    is_prime = False
                    break
            if is_prime:
                return candidate

    # We'll work with a copy of the list to avoid modifying while traversing
    # But since we need to modify in-place, we'll use a temporary list to collect results
    # Then rebuild the list.

    result_nodes = []
    current = head
    while current:
        new_val = find_next_prime(current.val)
        result_nodes.append(new_val)
        current = current.next

    # Rebuild the linked list
    if not result_nodes:
        return head

    new_head = ListNode(result_nodes[0])
    current_node = new_head
    for val in result_nodes[1:]:
        current_node.next = ListNode(val)
        current_node = current_node.next

    head.next = new_head
    return head

