def sort_array(arr):
    n = len(arr)
    # Create a copy to avoid modifying the original list
    result = arr.copy()

    for i in range(n - 1):
        for j in range(0, n - i - 1):
            # Compare adjacent elements
            if result[j] > result[j + 1]:
                # Swap elements
                temp = result[j]
                result[j] = result[j + 1]
                result[j + 1] = temp

