def int_to_roman(num):
    if not (1 <= num <= 3999):
        raise ValueError("Input must be between 1 and 3999")

    roman_map = {
        1000: 'M',
        900: 'CM',
        500: 'D',
        400: 'CD',
        100: 'C',
        90: 'XC',
        50: 'L',
        40: 'XL',
        10: 'X',
        9: 'IX',
        5: 'V',
        4: 'IV',
        1: 'I'
    }

    result = []
    while num > 0:
        for value, symbol in roman_map.items():
            if num >= value:
                result.append(symbol)
                num -= value
                break

    return ''.join(reversed(result))

