from functools import reduce

def validate_input(*args, **kwargs):
    def is_int_or_float(x):
        return isinstance(x, (int, float))

    def is_str_val(v):
        return isinstance(v, str)

    # Validate positional arguments
    pos_valid = filter(is_int_or_float, args)
    if not all(is_int_or_float(x) for x in pos_valid):
        return False

    # Validate keyword arguments
    key_valid = filter(is_str_val, kwargs.values())
    if not all(is_str_val(v) for v in key_valid):
        return False

    # If no arguments provided, return True
    if not args and not kwargs:
        return True

    # Combine results using reduce
    return reduce(lambda x, y: x and y, [
        is_int_or_float(x) for x in args if x is not None,
        is_str_val(v) for v in kwargs.values() if v is not None
    ])
